-- 1. Création des types énumérés (spécifique PostgreSQL)
CREATE TYPE niveau_classe AS ENUM ('L1', 'L2', 'L3');
CREATE TYPE sexe_type AS ENUM ('M', 'F');
CREATE TYPE type_evaluation_enum AS ENUM ('devoir', 'examen');
 
-- 2. Table CLASSE
CREATE TABLE CLASSE (
    id_classe INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    niveau niveau_classe NOT NULL,
    filiere VARCHAR(50) NOT NULL
);
 
-- 3. Table ETUDIANT
CREATE TABLE ETUDIANT (
    id_etudiant VARCHAR(20) PRIMARY KEY,
    nom VARCHAR(50) NOT NULL,
    prenom VARCHAR(50) NOT NULL,
    date_naissance DATE,
    sexe sexe_type NOT NULL,
    id_classe INT NOT NULL,
    FOREIGN KEY (id_classe) REFERENCES CLASSE(id_classe)
);
 
-- 4. Table PROFESSEUR
CREATE TABLE PROFESSEUR (
    id_professeur INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    nom VARCHAR(50) NOT NULL,
    prenom VARCHAR(50) NOT NULL,
    specialite VARCHAR(50)
);
 
-- 5. Table MATIERE
CREATE TABLE MATIERE (
    id_matiere INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    libelle VARCHAR(100) NOT NULL,
	coefficient INT
);
 
-- 6. Table de jonction ENSEIGNER (association n,n)
CREATE TABLE ENSEIGNER (
    id_professeur INT,
    id_matiere INT,
    PRIMARY KEY (id_professeur, id_matiere),
    FOREIGN KEY (id_professeur) REFERENCES PROFESSEUR(id_professeur),
    FOREIGN KEY (id_matiere) REFERENCES MATIERE(id_matiere)
);
 
-- 7. Table de jonction CONCERNER (association n,n)
CREATE TABLE CONCERNER (
    id_matiere INT,
    id_classe INT,
    PRIMARY KEY (id_matiere, id_classe),
    FOREIGN KEY (id_matiere) REFERENCES MATIERE(id_matiere),
    FOREIGN KEY (id_classe) REFERENCES CLASSE(id_classe)
);
 
-- 8. Table NOTE
CREATE TABLE NOTE (
    id_note INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    type_evaluation type_evaluation_enum NOT NULL,
    date_evaluation DATE NOT NULL,
    valeur DECIMAL(4,2),
    id_etudiant VARCHAR(20) NOT NULL,
    id_matiere INT NOT NULL,
    FOREIGN KEY (id_etudiant) REFERENCES ETUDIANT(id_etudiant),
    FOREIGN KEY (id_matiere) REFERENCES MATIERE(id_matiere)
);

SELECT valeur, date_evaluation
FROM Note
WHERE id_etudiant = 'ETU2025-00001' AND id_matiere = 3;


