--Afficher pour chaque note : le nom et prénom de l’étudiant, le nom de la matière, la valeur de la note et la date. 
SELECT 
    e.nom AS nom_etudiant,
    e.prenom AS prenom_etudiant,
    m.libelle AS nom_libelle,
    n.valeur AS note,
    n.date_evaluation AS date
FROM Note n
INNER JOIN Etudiant e ON n.id_etudiant = e.id_etudiant
INNER JOIN Matiere m ON n.id_matiere = m.id_matiere
ORDER BY n.date_evaluation DESC;


--Calculer la moyenne générale (par étudiant) de chaque étudiant, triée par moyenne décroissante. Afficher nom, prénom et moyenne.
SELECT 
    e.nom AS nom_etudiant,
    e.prenom AS prenom_etudiant,
    ROUND(AVG(n.valeur), 2) AS moyenne_generale
FROM Note n
INNER JOIN Etudiant e ON n.id_etudiant = e.id_etudiant
GROUP BY e.id_etudiant, e.nom, e.prenom
ORDER BY moyenne_generale DESC;


--Trouver les étudiants (nom, prénom) qui ont une note supérieure à la moyenne de toutes les notes dans la matière Mathématiques.
SELECT DISTINCT
    e.nom AS nom_etudiant,
    e.prenom AS prenom_etudiant
FROM Note n
INNER JOIN Etudiant e ON n.id_etudiant = e.id_etudiant
INNER JOIN Matiere m ON n.id_matiere = m.id_matiere
WHERE m.libelle = 'Informatique'
  AND n.valeur > (
      SELECT AVG(n2.valeur)
      FROM Note n2
      INNER JOIN Matiere m2 ON n2.id_matiere = m2.id_matiere
      WHERE m2.libelle = 'Informatique'
  );



--Pour chaque note, afficher l’étudiant, la matière, la note, ainsi que le rang de cette note au sein de la matière (du meilleur au moins bon). 
SELECT 
    e.nom AS nom_etudiant,
    e.prenom AS prenom_etudiant,
    m.libelle AS nom_matiere,
    n.valeur AS note,
    RANK() OVER (PARTITION BY n.id_matiere ORDER BY n.valeur DESC) AS rang
FROM Note n
INNER JOIN Etudiant e ON n.id_etudiant = e.id_etudiant
INNER JOIN Matiere m ON n.id_matiere = m.id_matiere
ORDER BY m.libelle, rang;


--Proposer un index permettant d’accélérer la recherche des notes par étudiant et par matière. Justifier. 
CREATE INDEX idx_note_etudiant_matiere
ON Note (id_etudiant, id_matiere);

